-Buffer::~Buffer() noexcept(false) {
-    if (not explicitly_destroy) {
-        destroy();
-    } else if (not destroyed) {
-        printf("WARNING: destroy() was not called before DeepEP buffer destruction, which can leak resources.\n");
-        fflush(stdout);
-    }
