+        // initialised by the dispatch warps once routing is done, see kDispatchWithLoadersBarrierIdx)
+        #pragma unroll
+        for (uint32_t i = lane_idx; i < kNumExperts; i += 32)
+            ptx::st_shared(smem_expert_count + i, 0u);
