+                        smem_weight_sf_wg[thread_idx_in_wg] = sf_pf_v0;
+                        smem_weight_sf_wg[kL1SFKBlocks + thread_idx_in_wg] = sf_pf_v1;
+                    }
+                } else {
+                    if (thread_idx_in_wg < kNumSFGroupsPerWG * kL2SFKBlocks)
