+    KU_CHECK_CONTIGUOUS(topk_length);
+    KU_CHECK_CONTIGUOUS(attn_sink);
+    KU_CHECK_CONTIGUOUS(tile_scheduler_metadata);
+    KU_CHECK_CONTIGUOUS(num_splits);
+    KU_CHECK_SHAPE(q, b, s_q, h_q, d_qk);
+    KU_CHECK_SHAPE(
+        packed_kv,
+        num_blocks,
+        PACKED_SPARSE_TILE_SIZE,
