+            b, s_q,
+            impl_meta.block_size_topk,
+            impl_meta.fixed_overhead_num_blocks,
+            topk,
+            0,
+            ku::get_optional_tensor_ptr<int>(topk_length),
+            nullptr,
+            nullptr,
+            (DecodingSchedMeta*)tile_scheduler_metadata->data_ptr(),
+            num_splits->data_ptr<int>(),
+            impl_meta.num_sm_parts,
